#!/usr/bin/env python3
"""Strict CSV parsing, formatting, JSON conversion, and command-line support."""

import csv
import io
import json
import sys


_HEADER = ["name", "note"]
_KEYS = {"name", "note"}


def _validate_quoting(text):
    """Reject quotes that do not follow CSV field-quoting rules."""
    in_quotes = False
    at_field_start = True
    just_closed = False
    index = 0

    while index < len(text):
        char = text[index]

        if in_quotes:
            if char == '"':
                if index + 1 < len(text) and text[index + 1] == '"':
                    index += 2
                    continue
                in_quotes = False
                just_closed = True
            index += 1
            continue

        if just_closed:
            if char == ",":
                just_closed = False
                at_field_start = True
            elif char == "\n":
                just_closed = False
                at_field_start = True
            elif char == "\r":
                just_closed = False
                at_field_start = True
                if index + 1 < len(text) and text[index + 1] == "\n":
                    index += 1
            else:
                raise ValueError(
                    "malformed CSV: unexpected character after closing quote"
                )
            index += 1
            continue

        if char == '"':
            if not at_field_start:
                raise ValueError("malformed CSV: quote inside an unquoted field")
            in_quotes = True
            at_field_start = False
        elif char == ",":
            at_field_start = True
        elif char == "\n":
            at_field_start = True
        elif char == "\r":
            at_field_start = True
            if index + 1 < len(text) and text[index + 1] == "\n":
                index += 1
        else:
            at_field_start = False
        index += 1

    if in_quotes:
        raise ValueError("malformed CSV: unterminated quoted field")


def parse_records(text):
    """Parse CSV with the exact header ``name,note`` into dictionaries."""
    if not isinstance(text, str):
        raise ValueError("CSV input must be a string")

    _validate_quoting(text)
    stream = io.StringIO(text, newline="")
    reader = csv.reader(stream, strict=True)

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("missing CSV header; expected name,note") from None
    except csv.Error as error:
        raise ValueError(f"malformed CSV: {error}") from None

    if header != _HEADER:
        raise ValueError("invalid CSV header; expected exactly name,note")

    records = []
    try:
        for row_number, row in enumerate(reader, start=2):
            if len(row) != 2:
                raise ValueError(
                    f"invalid column count on row {row_number}: expected 2, got {len(row)}"
                )
            records.append({"name": row[0], "note": row[1]})
    except csv.Error as error:
        raise ValueError(f"malformed CSV: {error}") from None

    return records


def format_records(records):
    """Serialize validated records as CSV using LF line terminators."""
    output = io.StringIO(newline="")
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(_HEADER)

    try:
        iterator = iter(records)
    except TypeError:
        raise ValueError("records must be an iterable of dictionaries") from None

    for position, record in enumerate(iterator, start=1):
        if not isinstance(record, dict):
            raise ValueError(f"record {position} must be a dictionary")
        if set(record) != _KEYS:
            raise ValueError(
                f"record {position} must contain exactly the keys name and note"
            )
        if not isinstance(record["name"], str) or not isinstance(record["note"], str):
            raise ValueError(f"record {position} values must be strings")
        try:
            writer.writerow([record["name"], record["note"]])
        except (csv.Error, TypeError) as error:
            raise ValueError(f"could not format record {position}: {error}") from None

    return output.getvalue()


def to_json(text):
    """Convert valid CSV text to JSON without ASCII-escaping Unicode values."""
    return json.dumps(parse_records(text), ensure_ascii=False)


def main():
    """Run the stdin-to-JSON command-line interface."""
    try:
        result = to_json(sys.stdin.read())
    except ValueError as error:
        sys.stderr.write(f"Error: {error}\n")
        return 2

    sys.stdout.write(result + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
